"""Shared calculation context: input, data registers, record list, lookups."""

from __future__ import annotations

from dataclasses import dataclass, field

from ...inputs.models import VesselInput
from ...materials import MaterialDatabase, MaterialError
from ...references import ReferenceRegister
from ...trace import CalcRecord
from ...units import G0

# Table UW-12 maximum allowable joint efficiencies (register: ASME8-1:TableUW-12)
TABLE_UW12 = {
    1: {"full": 1.00, "spot": 0.85, "none": 0.70},
    2: {"full": 0.90, "spot": 0.80, "none": 0.65},
    3: {"none": 0.60},
    4: {"none": 0.55},
    5: {"none": 0.50},
    6: {"none": 0.45},
}


def hydrostatic(height_mm: float, density_kg_m3: float) -> float:
    """rho g h in MPa: kg/m3 -> kg/mm3 (1e-9), times g in mm/s2 and h in mm
    gives kg/(mm s2) = 1e-3 N/mm2."""
    return density_kg_m3 * 1e-9 * G0 * height_mm * 1e-3


@dataclass
class Ctx:
    vi: VesselInput
    refs: ReferenceRegister
    matdb: MaterialDatabase
    records: list[CalcRecord] = field(default_factory=list)
    selected: dict[str, float] = field(default_factory=dict)       # nominal thickness by component
    available: dict[str, float] = field(default_factory=dict)      # corroded available thickness
    required: dict[str, float] = field(default_factory=dict)       # required t at E=1 (for UG-45 tb1)
    mawp_parts: dict[str, float] = field(default_factory=dict)     # MAWP at the top, per part
    mawp_notes: list[str] = field(default_factory=list)
    joint_E: dict[str, float] = field(default_factory=dict)
    geometry: dict | None = None

    def add(self, rec: CalcRecord) -> CalcRecord:
        if any(r.calc_id == rec.calc_id for r in self.records):
            raise ValueError(f"duplicate calc id {rec.calc_id}")
        self.records.append(rec)
        return rec

    # --- data quality -------------------------------------------------------
    def unverified(self, refs=(), materials=(), extra=()) -> list[str]:
        out = list(self.refs.unverified(refs))
        for m in materials:
            ma = self.vi.materials.get(m)
            if ma is None:
                out.append(f"material {m} undefined")
            elif not ma.record:
                if ma.status not in ("VERIFIED_OFFICIAL", "USER_SUPPLIED_VERIFIED"):
                    out.append(f"material {m} ({ma.label}) data {ma.status}")
            elif not ma.record.status.release_eligible:
                out.append(f"material {m} ({ma.record.id}) data {ma.record.status}")
        out.extend(extra)
        return out

    # --- material lookups -----------------------------------------------------
    def S(self, mat_key: str, T: float) -> tuple[float | None, str]:
        ma = self.vi.materials[mat_key]
        if ma.record is None:
            return None, f"{mat_key} is a non-pressure material without allowable stresses"
        try:
            return ma.record.allowable_stress(T)
        except MaterialError as exc:
            return None, str(exc)

    # --- pressure at an elevation -------------------------------------------
    def static_head(self, z_abs: float) -> float:
        """Liquid static head (MPa) at absolute elevation z (operating case)."""
        p = self.vi.process
        if p.liquid_level is None or p.liquid_density is None:
            return 0.0
        z_liq = self.vi.geometry.bottom_tangent_elevation + p.liquid_level
        return hydrostatic(max(0.0, z_liq - z_abs), p.liquid_density)

    def P_at(self, z_abs: float) -> float:
        return self.vi.process.design_pressure + self.static_head(z_abs)

    def joint(self, name: str):
        return self.vi.fabrication.joints.get(name)

"""ASME VIII-1 internal-pressure formulas as plain functions (SI: mm, MPa).

Each function states its rule, applicability limits and raises
``OutOfScope`` instead of returning a number outside those limits. Symbols:
P pressure, R/D/L/r corroded inside radius/diameter/crown/knuckle radius,
S allowable stress, E joint efficiency, t thickness (corroded, exclusive of
corrosion allowance). Register ids of the references are in ``REF``.
"""

from __future__ import annotations

import math


class OutOfScope(ValueError):
    """The formula's stated applicability limits are exceeded."""


REF = {
    "shell_circ": "ASME8-1:UG-27(c)(1)", "shell_long": "ASME8-1:UG-27(c)(2)",
    "ellipsoidal": "ASME8-1:App1-4(c)", "ellipsoidal_2to1": "ASME8-1:UG-32-ellipsoidal",
    "torispherical": "ASME8-1:App1-4(d)", "torispherical_std": "ASME8-1:UG-32-torispherical",
    "hemispherical": "ASME8-1:UG-32-hemispherical", "head_geometry": "ASME8-1:UG-32-geometry",
    "thin_head": "ASME8-1:App1-4(f)", "thick_shell": "ASME8-1:App1-2",
}

UG16B_MIN = 1.5  # mm, UG-16(b) minimum for shells and heads exclusive of CA


def _pos(**kw):
    for k, v in kw.items():
        if v is None or not v > 0:
            raise ValueError(f"{k} must be positive, got {v}")


def _eff(E):
    if not 0 < E <= 1:
        raise ValueError(f"joint efficiency must satisfy 0 < E <= 1, got {E}")


# --- cylindrical shells, UG-27 ------------------------------------------------

def shell_t_circ(P, R, S, E):
    """UG-27(c)(1): t = PR/(SE - 0.6P); valid for P <= 0.385SE and t <= R/2."""
    _pos(P=P, R=R, S=S), _eff(E)
    if P > 0.385 * S * E:
        raise OutOfScope(f"P = {P:g} MPa > 0.385SE = {0.385 * S * E:.3f} MPa: thick-wall rules "
                         "(Appendix 1-2) apply and are not implemented")
    t = P * R / (S * E - 0.6 * P)
    if t > R / 2:
        raise OutOfScope("t > R/2: Appendix 1-2 applies")
    return t


def shell_t_long(P, R, S, E):
    """UG-27(c)(2): t = PR/(2SE + 0.4P); valid for P <= 1.25SE and t <= R/2."""
    _pos(P=P, R=R, S=S), _eff(E)
    if P > 1.25 * S * E:
        raise OutOfScope(f"P > 1.25SE = {1.25 * S * E:.3f} MPa: Appendix 1-2 applies")
    t = P * R / (2 * S * E + 0.4 * P)
    if t > R / 2:
        raise OutOfScope("t > R/2: Appendix 1-2 applies")
    return t


def shell_mawp_circ(t, R, S, E):
    """UG-27(c)(1) solved for P: P = SEt/(R + 0.6t)."""
    _pos(t=t, R=R, S=S), _eff(E)
    if t > R / 2:
        raise OutOfScope("t > R/2: Appendix 1-2 applies")
    P = S * E * t / (R + 0.6 * t)
    if P > 0.385 * S * E:
        raise OutOfScope("resulting P exceeds 0.385SE")
    return P


def shell_mawp_long(t, R, S, E):
    """UG-27(c)(2) solved for P: P = 2SEt/(R - 0.4t)."""
    _pos(t=t, R=R, S=S), _eff(E)
    if t > R / 2:
        raise OutOfScope("t > R/2: Appendix 1-2 applies")
    return 2 * S * E * t / (R - 0.4 * t)


# --- formed heads, UG-32 / Appendix 1-4 ----------------------------------------

def ellipsoidal_K(ar):
    """Appendix 1-4(c): K = (2 + (D/2h)^2)/6, for 1.0 <= D/2h <= 3.0."""
    if not 1.0 <= ar <= 3.0:
        raise OutOfScope(f"D/2h = {ar:g} outside 1.0..3.0")
    return (2.0 + ar * ar) / 6.0


def ellipsoidal_t(P, D, S, E, ar=2.0):
    """t = PDK/(2SE - 0.2P) (K = 1 for 2:1 heads, the UG-32 form). The
    ts/L >= 0.002 applicability limit concerns the head's specified thickness,
    see ``thin_head_scope``."""
    _pos(P=P, D=D, S=S), _eff(E)
    K = ellipsoidal_K(ar)
    den = 2 * S * E - 0.2 * P
    if den <= 0:
        raise OutOfScope("2SE - 0.2P <= 0")
    return P * D * K / den


def head_crown_radius(kind, D, ar=2.0, L=None):
    """Inside crown radius used for the ts/L limit: torispherical L; for an
    ellipsoidal head the exact crown radius a^2/b = D*ar/2 (larger than the
    0.9D equivalent for 2:1 heads, so the limit is applied conservatively)."""
    if kind == "torispherical":
        return L
    if kind == "ellipsoidal":
        return D * ar / 2.0
    return None


def thin_head_scope(ts, L):
    """Formed-head rules apply for ts/L >= 0.002 (ts = specified minimum
    thickness after forming); thinner heads need Appendix 1-4(f)."""
    if L and ts / L < 0.002:
        raise OutOfScope(f"ts/L = {ts / L:.5f} < 0.002: Appendix 1-4(f) applies (not implemented)")


def ellipsoidal_mawp(t, D, S, E, ar=2.0):
    """P = 2SEt/(KD + 0.2t)."""
    _pos(t=t, D=D, S=S), _eff(E)
    return 2 * S * E * t / (ellipsoidal_K(ar) * D + 0.2 * t)


def torispherical_M(L, r):
    """Appendix 1-4(d): M = (3 + sqrt(L/r))/4, L/r <= 16 2/3."""
    _pos(L=L, r=r)
    if L / r > 50.0 / 3.0 + 1e-9:
        raise OutOfScope(f"L/r = {L / r:.3f} > 16 2/3")
    return 0.25 * (3.0 + math.sqrt(L / r))


def torispherical_t(P, L, r, S, E):
    """Appendix 1-4(d): t = PLM/(2SE - 0.2P)."""
    _pos(P=P, L=L, r=r, S=S), _eff(E)
    den = 2 * S * E - 0.2 * P
    if den <= 0:
        raise OutOfScope("2SE - 0.2P <= 0")
    return P * L * torispherical_M(L, r) / den


def torispherical_mawp(t, L, r, S, E):
    """P = 2SEt/(LM + 0.2t)."""
    _pos(t=t, L=L, r=r, S=S), _eff(E)
    return 2 * S * E * t / (L * torispherical_M(L, r) + 0.2 * t)


def torispherical_geometry_issues(L, r, Do_skirt, t):
    """Head geometry rules (crown radius <= skirt OD; knuckle >= 6 % skirt OD
    and >= 3t). Returns a list of violated conditions (empty = acceptable)."""
    issues = []
    if L > Do_skirt + 1e-9:
        issues.append(f"crown radius L = {L:.1f} mm exceeds skirt OD {Do_skirt:.1f} mm")
    if r < 0.06 * Do_skirt - 1e-9:
        issues.append(f"knuckle radius r = {r:.1f} mm < 6 % of skirt OD = {0.06 * Do_skirt:.1f} mm")
    if r < 3 * t - 1e-9:
        issues.append(f"knuckle radius r = {r:.1f} mm < 3t = {3 * t:.1f} mm")
    return issues


def hemispherical_t(P, L, S, E):
    """UG-32 hemispherical: t = PL/(2SE - 0.2P), P <= 0.665SE, t <= 0.356L."""
    _pos(P=P, L=L, S=S), _eff(E)
    if P > 0.665 * S * E:
        raise OutOfScope("P > 0.665SE: Appendix 1-3 applies (not implemented)")
    t = P * L / (2 * S * E - 0.2 * P)
    if t > 0.356 * L:
        raise OutOfScope("t > 0.356L: Appendix 1-3 applies (not implemented)")
    return t


def hemispherical_mawp(t, L, S, E):
    """P = 2SEt/(L + 0.2t)."""
    _pos(t=t, L=L, S=S), _eff(E)
    return 2 * S * E * t / (L + 0.2 * t)


# --- opening reinforcement, UG-37(c) / Fig. UG-37.1 / UG-40 --------------------

def area_replacement(*, d, t, tr, tn, trn, Sv, Sn, Sp=None, te=0.0, Dp=0.0, F=1.0, E1=1.0,
                     leg41=0.0, leg42=0.0, leg43=0.0, h=0.0, ti=0.0, inserted=True):
    """Area replacement for one opening; all thicknesses corroded.

    Returns every intermediate the report prints. Pad thickness and diameter
    beyond the UG-40 limits are not counted. Weld legs of 0 mean "not
    counted" (conservative when weld sizes are unknown)."""
    fr2 = min(Sn / Sv, 1.0)
    fr1 = fr2 if inserted else 1.0
    pad = te > 0 and Dp > 0
    fr4 = min((Sp if Sp is not None else Sv) / Sv, 1.0) if pad else 1.0
    fr3 = min(fr2, fr4) if pad else fr2
    Rn = d / 2.0
    lim_par = max(d, Rn + tn + t)
    lim_nor = min(2.5 * t, 2.5 * tn + te)
    te_eff = min(te, lim_nor) if pad else 0.0
    Dp_eff = min(Dp, 2.0 * lim_par) if pad else 0.0
    A = d * tr * F + 2.0 * tn * tr * F * (1.0 - fr1)
    ex = E1 * t - F * tr
    A1 = max(d * ex - 2.0 * tn * ex * (1.0 - fr1), 2.0 * (t + tn) * ex - 2.0 * tn * ex * (1.0 - fr1), 0.0)
    sur = max(tn - trn, 0.0)
    if pad:
        A2 = min(5.0 * sur * fr2 * t, 2.0 * sur * (2.5 * tn + te_eff) * fr2)
    else:
        A2 = min(5.0 * sur * fr2 * t, 5.0 * sur * fr2 * tn)
    A3 = min(5.0 * t * ti * fr2, 5.0 * ti * ti * fr2, 2.0 * h * ti * fr2) if h > 0 and ti > 0 else 0.0
    A41 = leg41 ** 2 * (fr3 if pad else fr2)
    A42 = leg42 ** 2 * fr4 if pad else 0.0
    A43 = leg43 ** 2 * fr2 if h > 0 else 0.0
    A5 = max(Dp_eff - d - 2.0 * tn, 0.0) * te_eff * fr4 if pad else 0.0
    total = A1 + A2 + A3 + A41 + A42 + A43 + A5
    return {"fr1": fr1, "fr2": fr2, "fr3": fr3, "fr4": fr4, "limit_parallel": lim_par,
            "limit_normal": lim_nor, "te_eff": te_eff, "Dp_eff": Dp_eff, "excess_shell": ex,
            "surplus_nozzle": sur, "A": A, "A1": A1, "A2": A2, "A3": A3, "A41": A41, "A42": A42,
            "A43": A43, "A5": A5, "A_avail": total, "adequate": total >= A - 1e-9}


# --- plate undertolerance, UG-16(c) -------------------------------------------

def plate_undertolerance_deduction(t_nominal, undertolerance):
    """UG-16(c): an undertolerance not exceeding the smaller of 0.25 mm or 6 %
    of the ordered thickness may be ignored; a larger one is deducted."""
    if undertolerance is None:
        return 0.0, "undertolerance not stated: taken as 0 (needs review)"
    limit = min(0.25, 0.06 * t_nominal)
    if undertolerance <= limit + 1e-12:
        return 0.0, f"undertolerance {undertolerance:g} mm <= min(0.25 mm, 6 %) = {limit:.3f} mm: ignored"
    return undertolerance, f"undertolerance {undertolerance:g} mm > {limit:.3f} mm: deducted"

"""Input validation for the ASME VIII-1 vessel schema (pv-design/vessel@1).

The validator never fills a missing safety-relevant value. A missing required
field is an error; a missing optional field that a check needs becomes a
question for the user and, later, a NOT_EVALUATED check. Every dimensional
value needs an explicit unit (see units.py).
"""

from __future__ import annotations

import hashlib
import json
import math
from dataclasses import dataclass, field

from .. import pipes, units
from ..materials import MaterialDatabase, MaterialError, record_from_dict
from ..status import DataStatus
from .models import (DesignBasis, Fabrication, Flange, FlangeDims, Geometry, Head, Joint, Legs,
                     LoadItem, Lugs, MaterialAssignment, Neck, Nozzle, Pad, Process, Project,
                     ShellCourse, VesselInput)

SCHEMA_ID = "pv-design/vessel@1"
NONE_TOKENS = {"none", "null", "n/a", "na", "", "-"}
UNSTATED_TOKENS = {"tbd", "not_stated", "unknown", "to be confirmed"}
DESIGN_CODES = {"ASME_VIII_1", "API_650", "API_620", "EN_13445", "ASME_VIII_2"}
HEAD_TYPES = {"ellipsoidal", "torispherical", "hemispherical"}
RT_LEVELS = {"full", "spot", "none"}
LOAD_KEYS = ["wind", "seismic", "piping_loads", "snow", "lifting", "transport", "thermal"]


@dataclass
class Issue:
    field: str
    message: str

    def __str__(self):
        return f"{self.field}: {self.message}"


@dataclass
class ValidationReport:
    errors: list[Issue] = field(default_factory=list)
    warnings: list[Issue] = field(default_factory=list)
    questions: list[Issue] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        return not self.errors

    def to_dict(self) -> dict:
        return {"ok": self.ok, "errors": [vars(i) for i in self.errors],
                "warnings": [vars(i) for i in self.warnings],
                "questions": [vars(i) for i in self.questions]}


class _Missing:
    pass


MISSING = _Missing()


def _is_none(v) -> bool:
    return v is None or (isinstance(v, str) and v.strip().lower() in NONE_TOKENS)


def _is_unstated(v) -> bool:
    return isinstance(v, str) and v.strip().lower() in UNSTATED_TOKENS


class _Ctx:
    def __init__(self, rep: ValidationReport):
        self.rep = rep

    def err(self, path, msg):
        self.rep.errors.append(Issue(path, msg))

    def warn(self, path, msg):
        self.rep.warnings.append(Issue(path, msg))

    def ask(self, path, msg):
        self.rep.questions.append(Issue(path, msg))

    def get(self, d: dict, key: str):
        if not isinstance(d, dict):
            return MISSING
        return d.get(key, MISSING)

    def quantity(self, d, key, path, dim, *, required=True, question=None, positive=False,
                 non_negative=False):
        v = self.get(d, key)
        p = f"{path}.{key}"
        if v is MISSING or _is_none(v) or _is_unstated(v):
            if required:
                self.err(p, "required value missing" + (f" — {question}" if question else ""))
            elif question:
                self.ask(p, question)
            return None
        try:
            q = units.parse(v, expect=dim, field=p)
        except units.UnitError as exc:
            self.err(p, str(exc))
            return None
        if positive and not q.value > 0:
            self.err(p, f"must be positive, got {q.text}")
            return None
        if non_negative and q.value < 0:
            self.err(p, f"must not be negative, got {q.text}")
            return None
        return q

    def value(self, d, key, path, dim, **kw) -> float | None:
        q = self.quantity(d, key, path, dim, **kw)
        return None if q is None else q.value

    def angle(self, d, key, path, *, required=True) -> float | None:
        v = self.get(d, key)
        p = f"{path}.{key}"
        if v is MISSING or _is_none(v):
            if required:
                self.err(p, "required angle missing (write e.g. '90 deg')")
            return None
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            self.err(p, f"{v!r} has no unit; write it as '{v} deg'")
            return None
        s = str(v).strip().lower().replace("°", " deg")
        try:
            num, u = units._split(s)
        except units.UnitError as exc:
            self.err(p, str(exc))
            return None
        if u in ("deg", "degree", "degrees"):
            return num % 360.0
        if u == "rad":
            return math.degrees(num) % 360.0
        self.err(p, f"unknown angle unit {u!r}; use deg")
        return None

    def text(self, d, key, path, *, required=True, choices=None, question=None) -> str | None:
        v = self.get(d, key)
        p = f"{path}.{key}"
        if v is MISSING or _is_none(v):
            if required:
                self.err(p, "required text missing" + (f" — {question}" if question else ""))
            elif question:
                self.ask(p, question)
            return None
        s = str(v).strip()
        if choices and s not in choices:
            self.err(p, f"{s!r} is not one of {sorted(choices)}")
            return None
        return s

    def flag(self, d, key, path, *, required=False, question=None) -> bool | None:
        v = self.get(d, key)
        p = f"{path}.{key}"
        if v is MISSING or _is_none(v) or _is_unstated(v):
            if required:
                self.err(p, "required true/false missing")
            elif question:
                self.ask(p, question)
            return None
        if isinstance(v, bool):
            return v
        self.err(p, f"expected true or false, got {v!r}")
        return None

    def number(self, d, key, path, *, required=True, integer=False, lo=None, hi=None) -> float | None:
        v = self.get(d, key)
        p = f"{path}.{key}"
        if v is MISSING or _is_none(v):
            if required:
                self.err(p, "required number missing")
            return None
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            self.err(p, f"expected a plain number, got {v!r}")
            return None
        if integer and int(v) != v:
            self.err(p, f"expected an integer, got {v!r}")
            return None
        if (lo is not None and v < lo) or (hi is not None and v > hi):
            self.err(p, f"{v!r} outside the allowed range [{lo}, {hi}]")
            return None
        return int(v) if integer else float(v)


def input_hash(raw: dict) -> str:
    blob = json.dumps(raw, sort_keys=True, default=str, ensure_ascii=False).encode("utf-8")
    return hashlib.sha256(blob).hexdigest()


# ---------------------------------------------------------------------------

def validate_vessel(raw: dict, matdb: MaterialDatabase, *, source_path: str = ""
                    ) -> tuple[VesselInput | None, ValidationReport]:
    rep = ValidationReport()
    c = _Ctx(rep)
    if not isinstance(raw, dict):
        c.err("<root>", "input must be a mapping")
        return None, rep
    if raw.get("schema") != SCHEMA_ID:
        c.err("schema", f"expected {SCHEMA_ID!r}, got {raw.get('schema')!r}")

    pr = raw.get("project", {})
    project = Project(
        project_id=c.text(pr, "project_id", "project") or "",
        equipment_tag=c.text(pr, "equipment_tag", "project") or "",
        description=c.text(pr, "description", "project") or "",
        customer=c.text(pr, "customer", "project", required=False) or "",
        design_code=c.text(pr, "design_code", "project", choices=DESIGN_CODES) or "",
        code_edition=c.text(pr, "code_edition", "project",
                            question="state the code edition (year) and addenda the design is to") or "",
        addenda=c.text(pr, "addenda", "project", required=False) or "none stated",
        units_system=c.text(pr, "units_system", "project", choices={"SI", "US"}) or "SI",
        design_status=c.text(pr, "design_status", "project", required=False) or "PRELIMINARY",
        revision=str(pr.get("revision", "")) if pr.get("revision") is not None else (c.err("project.revision", "required") or ""),
        data_status=c.text(pr, "data_status", "project", choices={"DEMO_SAMPLE", "USER_CONFIRMED"}) or "DEMO_SAMPLE",
        jurisdiction=c.text(pr, "jurisdiction", "project", required=False,
                            question="state the installation country/jurisdiction and its inspection rules") or "not stated",
        prepared_by=c.text(pr, "prepared_by", "project", required=False) or "",
        date=str(pr.get("date", "")),
    )
    if project.design_code and project.design_code != "ASME_VIII_1":
        c.err("project.design_code", f"{project.design_code} input must use its own schema; this "
              "validator is for ASME_VIII_1 vessels (API 650 tanks use pv-design/tank@1)")

    db = raw.get("design_basis", {})
    basis = DesignBasis(locked=bool(db.get("locked", False)), confirmed_by=db.get("confirmed_by"),
                        confirmed_on=db.get("confirmed_on"), notes=list(db.get("notes", []) or []))
    if basis.locked and not (basis.confirmed_by and basis.confirmed_on):
        c.err("design_basis", "locked: true requires confirmed_by and confirmed_on")
    if basis.locked and project.data_status != "USER_CONFIRMED":
        c.err("design_basis", "a design basis built on DEMO_SAMPLE data cannot be locked")

    process = _process(c, raw.get("process", {}))
    materials = _materials(c, raw.get("materials", {}), matdb)
    fab = _fabrication(c, raw.get("fabrication", {}))
    geometry = _geometry(c, raw.get("geometry", {}), raw.get("flange_types", {}) or {}, materials,
                         process, fab)
    loads = _loads(c, raw.get("loads", {}), geometry)
    ext = _external_data(c, raw.get("external_pressure_data", {}) or {}, process)

    if process and process.operating_pressure is not None and process.operating_pressure > process.design_pressure:
        c.err("process.operating_pressure", "operating pressure exceeds design pressure")
    if process and process.operating_temperature is not None and process.operating_temperature > process.design_temperature:
        c.err("process.operating_temperature", "operating temperature exceeds design temperature")
    if process and process.mdmt > process.design_temperature:
        c.err("process.mdmt", "MDMT is above the design temperature")
    if process and process.design_pressure > 20.7:
        c.warn("process.design_pressure", "above 20.7 MPa (3000 psi): VIII-1 may require additional "
               "design rules; thick-wall cases are OUT_OF_SCOPE here")

    if rep.errors or process is None or geometry is None:
        return None, rep
    assessments = _assessments(c, raw.get("assessments") or {})
    if rep.errors:
        return None, rep
    vi = VesselInput(project=project, design_basis=basis, process=process, geometry=geometry,
                     materials=materials, fabrication=fab, loads=loads, external_pressure_data=ext,
                     assessments=assessments,
                     reference_verification=list((raw.get("code_reference_verification") or {}).get("verified", []) or []),
                     source_path=source_path, input_hash=input_hash(raw), raw=raw)
    return vi, rep


def _process(c: _Ctx, d: dict) -> Process | None:
    P = "process"
    L, PR, T = units.LENGTH, units.PRESSURE, units.TEMPERATURE
    dp = c.quantity(d, "design_pressure", P, PR, non_negative=True)
    if dp is not None and dp.pressure_ref == "a":
        c.err(f"{P}.design_pressure", "give the design pressure as gauge (e.g. 'MPa(g)', 'barg'); "
              "absolute values need an explicit atmospheric reference")
        dp = None
    ext_raw = c.get(d, "external_pressure")
    ext = None
    if not (ext_raw is MISSING or _is_none(ext_raw)):
        ext = c.value(d, "external_pressure", P, PR, non_negative=True)
    else:
        c.warn(f"{P}.external_pressure", "no external pressure / vacuum stated: external-pressure "
               "checks will be listed as not required — confirm that no vacuum case exists")
    fluid_phase = c.text(d, "fluid_phase", P, choices={"gas", "liquid", "two_phase"})
    level = c.value(d, "liquid_level", P, L, required=False, non_negative=True)
    rho = c.value(d, "liquid_density", P, units.DENSITY, required=False, positive=True)
    if fluid_phase in ("liquid", "two_phase") and (level is None or rho is None):
        c.ask(f"{P}.liquid_level", "liquid service: give the maximum liquid level above the bottom "
              "tangent line and the liquid density, so static head can be added (UG-22, UG-98)")
    test_type = c.text(d, "test_type", P, choices={"hydrostatic", "pneumatic"})
    test_basis = c.text(d, "test_basis", P, choices={"MAWP", "design_pressure"})
    pos = c.text(d, "test_position", P, choices={"vertical", "horizontal"}, required=False) or "vertical"
    trho = c.value(d, "test_fluid_density", P, units.DENSITY, required=test_type == "hydrostatic",
                   positive=True)
    vals = dict(
        fluid=c.text(d, "fluid", P) or "",
        fluid_phase=fluid_phase or "",
        lethal_service=c.flag(d, "lethal_service", P, question="state whether the service is lethal (UW-2)"),
        cyclic_service=c.flag(d, "cyclic_service", P, question="state whether the vessel is in cyclic "
                              "service (fatigue screening is required if so)"),
        operating_pressure=c.value(d, "operating_pressure", P, PR, required=False),
        design_pressure=None if dp is None else dp.value,
        operating_temperature=c.value(d, "operating_temperature", P, T, required=False),
        design_temperature=c.value(d, "design_temperature", P, T),
        mdmt=c.value(d, "mdmt", P, T),
        external_pressure=ext,
        external_design_temperature=c.value(d, "external_design_temperature", P, T,
                                            required=ext is not None and ext > 0),
        required_volume=c.value(d, "required_volume", P, units.VOLUME, required=False, positive=True),
        liquid_level=level, liquid_density=rho,
        corrosion_allowance=c.value(d, "corrosion_allowance", P, L, non_negative=True),
        test_type=test_type or "", test_basis=test_basis or "",
        test_temperature=c.value(d, "test_temperature", P, T),
        test_position=pos, test_fluid_density=trho,
    )
    if vals["corrosion_allowance"] is not None and vals["corrosion_allowance"] > 6.0:
        c.warn(f"{P}.corrosion_allowance", "corrosion allowance above 6 mm — confirm")
    if any(vals[k] is None for k in ("design_pressure", "design_temperature", "mdmt", "corrosion_allowance",
                                       "test_temperature")):
        return None
    return Process(**vals)


def _materials(c: _Ctx, d: dict, matdb: MaterialDatabase) -> dict[str, MaterialAssignment]:
    out = {}
    if not isinstance(d, dict) or not d:
        c.err("materials", "at least one material assignment is required")
        return out
    for key, m in d.items():
        p = f"materials.{key}"
        if not isinstance(m, dict):
            c.err(p, "must be a mapping")
            continue
        if m.get("non_pressure"):
            rho = c.value(m, "density", p, units.DENSITY, positive=True)
            st = str(m.get("verification_status", "UNVERIFIED"))
            if st not in DataStatus.__members__:
                c.err(f"{p}.verification_status", f"unknown status {st!r}")
            out[key] = MaterialAssignment(key, None, True, c.text(m, "spec", p) or "", rho, st,
                                          c.value(m, "min_yield", p, units.PRESSURE, required=False))
            continue
        if "db_id" in m:
            try:
                out[key] = MaterialAssignment(key, matdb.get(m["db_id"]))
            except MaterialError as exc:
                c.err(f"{p}.db_id", str(exc))
            continue
        if "record" in m:
            try:
                rec = record_from_dict(m["record"])
                matdb.add(rec, replace=False)
                out[key] = MaterialAssignment(key, rec)
            except (MaterialError, KeyError) as exc:
                c.err(f"{p}.record", f"invalid inline material record: {exc}")
            continue
        c.err(p, "give db_id (material database id), an inline 'record', or non_pressure: true")
    return out


def _joint(c: _Ctx, d, name) -> Joint | None:
    p = f"fabrication.joints.{name}"
    if not isinstance(d, dict):
        c.err(p, "joint definition missing: state category, joint_type (Table UW-12) and radiography "
              "(full/spot/none). No default joint efficiency is assumed.")
        return None
    cat = c.text(d, "category", p, choices={"A", "B", "C", "D"})
    jt = c.number(d, "joint_type", p, integer=True, lo=1, hi=6)
    rt = c.text(d, "radiography", p, choices=RT_LEVELS)
    if None in (cat, jt, rt):
        return None
    return Joint(name, cat, int(jt), rt)


def _fabrication(c: _Ctx, d: dict) -> Fabrication:
    p = "fabrication"
    jd = c.get(d, "joints")
    joints = {}
    for name in ("shell_longitudinal", "shell_circumferential", "head_to_shell"):
        j = _joint(c, (jd or {}).get(name) if isinstance(jd, dict) else None, name)
        if j:
            joints[name] = j
    pt = c.get(d, "plate_thicknesses")
    plates: list[float] = []
    if isinstance(pt, dict) and "values" in pt and "unit" in pt:
        try:
            plates = sorted(units.convert(float(v), str(pt["unit"]), expect=units.LENGTH).value
                            for v in pt["values"])
        except (units.UnitError, TypeError, ValueError) as exc:
            c.err(f"{p}.plate_thicknesses", str(exc))
    elif not (pt is MISSING or _is_none(pt)):
        c.err(f"{p}.plate_thicknesses", "write as {values: [6, 8, 10], unit: mm}")

    def fraction(key):
        q = c.quantity(d, key, p, units.FRACTION, required=False, non_negative=True)
        return None if q is None else q.value

    def assessment(key):
        v = c.get(d, key)
        if v is MISSING or _is_none(v):
            return None
        if not isinstance(v, dict) or not {"result", "basis", "by"} <= set(v):
            c.err(f"{p}.{key}", "an assessment needs result, basis and by")
            return None
        return v

    return Fabrication(
        joints=joints,
        spot_rt_uw11a5b=c.flag(d, "spot_rt_meets_uw11a5b", p,
                               question="state whether the spot radiography of UW-11(a)(5)(b) is met "
                                        "(controls E for seamless heads, UW-12(d))"),
        plate_thicknesses=plates,
        plate_undertolerance=c.value(d, "plate_undertolerance", p, units.LENGTH, required=False,
                                     non_negative=True,
                                     question="state the plate mill undertolerance (UG-16(c))"),
        pipe_undertolerance=fraction("pipe_undertolerance"),
        cutting_allowance=fraction("cutting_allowance"),
        scrap_allowance=fraction("scrap_allowance"),
        nde=str(d.get("nde", "not stated")), pwht=str(d.get("pwht", "not stated")),
        impact_testing=str(d.get("impact_testing", "not stated")),
        mdmt_assessment=assessment("mdmt_assessment"), pwht_assessment=assessment("pwht_assessment"),
        general_tolerances=str(d.get("general_tolerances", "not specified")),
    )


def _flange(c: _Ctx, d, path, types: dict, materials) -> Flange | None:
    if _is_none(d):
        return None
    if not isinstance(d, dict):
        c.err(path, "flange must be a mapping or none")
        return None
    ref = d.get("type_ref")
    base = {}
    if ref is not None:
        if ref not in types:
            c.err(f"{path}.type_ref", f"unknown flange type {ref!r}; define it under flange_types")
            return None
        base = dict(types[ref])
    merged = {**base, **{k: v for k, v in d.items() if k != "type_ref"}}
    mat = c.text(merged, "material", path)
    if mat and mat not in materials:
        c.err(f"{path}.material", f"material key {mat!r} not defined under materials")
    dims = None
    dd = merged.get("dimensions")
    if isinstance(dd, dict):
        L = units.LENGTH
        dp = f"{path}.dimensions"
        dims = FlangeDims(
            od=c.value(dd, "od", dp, L, positive=True) or 0.0,
            thickness=c.value(dd, "thickness", dp, L, positive=True) or 0.0,
            hub_od=c.value(dd, "hub_od", dp, L, required=False, positive=True),
            length_through_hub=c.value(dd, "length_through_hub", dp, L, required=False, positive=True),
            bolt_circle=c.value(dd, "bolt_circle", dp, L, positive=True) or 0.0,
            bolt_holes=int(c.number(dd, "bolt_holes", dp, integer=True, lo=4, hi=200) or 0),
            bolt_hole_diameter=c.value(dd, "bolt_hole_diameter", dp, L, positive=True) or 0.0,
            bolt_size=str(dd.get("bolt_size", "")),
            raised_face_od=c.value(dd, "raised_face_od", dp, L, required=False, positive=True),
            raised_face_height=c.value(dd, "raised_face_height", dp, L, required=False, non_negative=True),
            source=str(merged.get("dimensions_source", "not stated")),
            status=str(merged.get("dimensions_status", "UNVERIFIED")))
    else:
        c.ask(f"{path}.dimensions", "flange dimensions not given: the 3D model and drawings will show "
              "the flange only as a neck end")
    # a missing rating is asked for by the NZ-<tag>-FLG calculation record
    rating = c.value(merged, "rating_at_design_temperature", path, units.PRESSURE, required=False,
                     positive=True)
    return Flange(
        type_ref=str(ref or ""), standard=str(merged.get("standard", "")),
        pressure_class=str(merged.get("class", "")), flange_type=str(merged.get("type", "")),
        facing=str(merged.get("facing", "")), material=mat or "",
        rating_at_design_temperature=rating, rating_source=str(merged.get("rating_source", "")),
        rating_status=str(merged.get("rating_status", "UNVERIFIED")), dims=dims,
        blind_cover=bool(merged.get("blind_cover", False)),
        supply_bolting=bool(merged.get("supply_bolting", False)),
        gasket=str(merged.get("gasket", "not specified")), bolting=str(merged.get("bolting", "not specified")))


def _neck(c: _Ctx, d, path, materials) -> Neck | None:
    if not isinstance(d, dict):
        c.err(path, "neck definition missing")
        return None
    kind = c.text(d, "type", path, choices={"pipe", "plate"})
    mat = c.text(d, "material", path)
    if mat and mat not in materials:
        c.err(f"{path}.material", f"material key {mat!r} not defined under materials")
    if kind == "pipe":
        if "nps" in d:
            try:
                ps = pipes.lookup(d["nps"], d.get("schedule", ""))
            except KeyError as exc:
                c.err(f"{path}.nps", str(exc))
                return None
            return Neck("pipe", ps.od, ps.wall, mat or "", ps.nps, ps.schedule, ps.std_wall,
                        ps.source, ps.status)
        od = c.value(d, "od", path, units.LENGTH, positive=True)
        wall = c.value(d, "wall", path, units.LENGTH, positive=True)
        if od is None or wall is None:
            return None
        return Neck("pipe", od, wall, mat or "", None, None, None, "user input", "USER_SUPPLIED_UNVERIFIED")
    if kind == "plate":
        od = c.value(d, "od", path, units.LENGTH, positive=True)
        wall = c.value(d, "thickness", path, units.LENGTH, positive=True)
        seam_E = c.number(d, "seam_joint_efficiency", path, lo=0.45, hi=1.0)
        if od is None or wall is None:
            return None
        std = None
        if d.get("equivalent_nps") is not None:
            try:
                std = pipes.lookup(d["equivalent_nps"], "STD").std_wall
            except KeyError as exc:
                c.err(f"{path}.equivalent_nps", str(exc))
        return Neck("plate", od, wall, mat or "", str(d.get("equivalent_nps")) if d.get("equivalent_nps") else None,
                    None, std, "user input", "USER_SUPPLIED_UNVERIFIED", seam_E)
    return None


def _head(c: _Ctx, d, pos, materials) -> Head | None:
    p = f"geometry.heads.{pos}"
    if not isinstance(d, dict):
        c.err(p, "head definition missing")
        return None
    typ = c.text(d, "type", p, choices=HEAD_TYPES)
    L = units.LENGTH
    ar = kr = cr = None
    if typ == "ellipsoidal":
        ar = c.number(d, "aspect_ratio", p, lo=1.0, hi=3.0)
    if typ == "torispherical":
        cr = c.value(d, "crown_radius", p, L, positive=True)
        kr = c.value(d, "knuckle_radius", p, L, positive=True)
    mat = c.text(d, "material", p)
    if mat and mat not in materials:
        c.err(f"{p}.material", f"material key {mat!r} not defined")
    nom_raw = c.get(d, "nominal_thickness")
    nom = None
    if isinstance(nom_raw, str) and nom_raw.strip().lower() == "auto":
        fa = c.value(d, "forming_allowance", p, L, non_negative=True,
                     question="automatic head thickness needs the forming (thinning) allowance from the head maker")
        tmin = None
    else:
        nom = c.value(d, "nominal_thickness", p, L, positive=True)
        tmin = c.value(d, "min_thickness_after_forming", p, L, required=False, positive=True)
        fa = c.value(d, "forming_allowance", p, L, required=False, non_negative=True)
        if tmin is None and fa is None:
            c.err(p, "give min_thickness_after_forming or forming_allowance (UG-32 uses the minimum "
                  "thickness after forming; it is not assumed equal to the nominal plate)")
        if tmin is not None and nom is not None and tmin > nom:
            c.err(f"{p}.min_thickness_after_forming", "exceeds the nominal plate thickness")
    construction = c.text(d, "construction", p, choices={"seamless", "welded"})
    jeo = c.number(d, "joint_efficiency", p, required=construction == "welded", lo=0.3, hi=1.0)
    if typ is None or mat is None or construction is None:
        return None
    return Head(pos, typ, ar, cr, kr, c.value(d, "straight_flange", p, L, non_negative=True) or 0.0,
                mat, construction, nom, tmin, fa, jeo)


def _geometry(c: _Ctx, d: dict, flange_types: dict, materials, process, fab) -> Geometry | None:
    p = "geometry"
    L = units.LENGTH
    orient = c.text(d, "orientation", p, choices={"vertical", "horizontal"})
    if orient == "horizontal":
        c.err(f"{p}.orientation", "horizontal vessels (saddles, Zick analysis) are OUT_OF_SCOPE in "
              "v0.1; the calculation core is orientation independent but the geometry/CAD/support "
              "layers are vertical only")
    basis = c.text(d, "diameter_basis", p, choices={"ID"})
    D = c.value(d, "diameter", p, L, positive=True)
    tt = c.value(d, "tangent_to_tangent", p, L, positive=True)
    btl = c.value(d, "bottom_tangent_elevation", p, L, non_negative=True)
    courses = []
    for i, cd in enumerate(d.get("shell_courses") or []):
        cp = f"{p}.shell_courses[{i}]"
        mat = c.text(cd, "material", cp)
        if mat and mat not in materials:
            c.err(f"{cp}.material", f"material key {mat!r} not defined")
        nt = cd.get("nominal_thickness")
        nom = None if (isinstance(nt, str) and nt.strip().lower() == "auto") else \
            c.value(cd, "nominal_thickness", cp, L, positive=True)
        if nom is None and not fab.plate_thicknesses:
            c.err(f"{cp}.nominal_thickness", "auto selection needs fabrication.plate_thicknesses")
        courses.append(ShellCourse(c.text(cd, "id", cp) or f"C{i + 1}",
                                   c.value(cd, "length", cp, L, positive=True) or 0.0, mat or "", nom,
                                   c.angle(cd, "long_seam_orientation", cp, required=False)))
    if not courses:
        c.err(f"{p}.shell_courses", "at least one shell course is required")
    hd = d.get("heads") or {}
    heads = {}
    for pos in ("top", "bottom"):
        h = _head(c, hd.get(pos), pos, materials)
        if h:
            heads[pos] = h
    if tt and courses and len(heads) == 2:
        total = sum(cc.length for cc in courses) + sum(h.straight_flange for h in heads.values())
        if abs(total - tt) > 0.5:
            c.err(f"{p}.shell_courses", f"course lengths {sum(cc.length for cc in courses):g} mm + "
                  f"straight flanges {sum(h.straight_flange for h in heads.values()):g} mm = {total:g} mm "
                  f"does not equal the tangent-to-tangent length {tt:g} mm")
    nozzles = []
    tags = set()
    for i, nd in enumerate(d.get("nozzles") or []):
        np_ = f"{p}.nozzles[{i}]"
        tag = c.text(nd, "tag", np_)
        if tag in tags:
            c.err(f"{np_}.tag", f"duplicate nozzle tag {tag}")
        tags.add(tag)
        loc = c.text(nd, "location", np_, choices={"shell", "top_head", "bottom_head"})
        neck = _neck(c, nd.get("neck"), f"{np_}.neck", materials)
        pad = None
        pd = nd.get("pad")
        if not _is_none(pd):
            pp = f"{np_}.pad"
            te = c.value(pd, "thickness", pp, L, positive=True)
            dp_ = c.value(pd, "outside_diameter", pp, L, positive=True)
            pm = c.text(pd, "material", pp)
            if pm and pm not in materials:
                c.err(f"{pp}.material", f"material key {pm!r} not defined")
            if te and dp_ and pm:
                pad = Pad(te, dp_, pm)
        wl = nd.get("welds") or {}
        legs = {}
        for k in ("nozzle_outer_leg", "pad_outer_leg", "inner_leg"):
            legs[k] = c.value(wl, k, f"{np_}.welds", L, required=False, non_negative=True)
        if all(v is None for v in legs.values()):
            c.warn(f"{np_}.welds", "no weld sizes: weld areas A41-A43 are taken as zero (conservative) "
                   "and weld strength (UG-41) is NOT_EVALUATED")
        elev = c.value(nd, "elevation", np_, L, required=loc == "shell")
        offset = c.value(nd, "offset", np_, L, required=False, non_negative=True) or 0.0
        if loc != "shell" and offset > 0:
            c.err(f"{np_}.offset", "off-centre head nozzles (hillside/radial in the knuckle) are "
                  "OUT_OF_SCOPE in v0.1; place head nozzles on the head centreline")
        att = c.text(nd, "attachment", np_, choices={"set_in", "set_on"})
        if neck and tag and loc and att:
            nozzles.append(Nozzle(
                tag=tag, service=c.text(nd, "service", np_, required=False) or "", location=loc,
                elevation=elev, orientation=c.angle(nd, "orientation", np_, required=loc == "shell") or 0.0,
                offset=offset, projection=c.value(nd, "projection", np_, L, positive=True) or 0.0,
                neck=neck, attachment=att,
                inward_projection=c.value(nd, "inward_projection", np_, L, required=False, non_negative=True) or 0.0,
                flange=_flange(c, nd.get("flange"), f"{np_}.flange", flange_types, materials),
                pad=pad, weld_legs=legs, access_opening=bool(nd.get("access_opening", False))))
    legs = None
    sd = d.get("supports")
    if isinstance(sd, dict) and sd.get("type") == "legs":
        sp = f"{p}.supports"
        lg = sd.get("leg", {})
        legs = Legs(count=int(c.number(sd, "count", sp, integer=True, lo=3, hi=12) or 0),
                    orientation_start=c.angle(sd, "orientation_start", sp) or 0.0,
                    section=str(lg.get("section", "")),
                    od=c.value(lg, "od", f"{sp}.leg", L, positive=True) or 0.0,
                    wall=c.value(lg, "wall", f"{sp}.leg", L, positive=True) or 0.0,
                    material=c.text(lg, "material", f"{sp}.leg") or "",
                    top_elevation=c.value(sd, "top_elevation", sp, L, positive=True) or 0.0,
                    base_plate=_base_plate(c, sd.get("base_plate") or {}, f"{sp}.base_plate"))
    elif sd is not None and not _is_none(sd):
        c.err(f"{p}.supports", "only supports.type: legs is implemented in v0.1 (skirt and saddles are OUT_OF_SCOPE)")
    else:
        c.ask(f"{p}.supports", "no supports defined: support loads and the support model will be absent")
    lugs = None
    ld = d.get("lifting_lugs")
    if isinstance(ld, dict):
        lp = f"{p}.lifting_lugs"
        al = ld.get("allowables")
        allow = None
        if isinstance(al, dict):
            allow = {k: c.value(al, k, f"{lp}.allowables", units.PRESSURE, positive=True)
                     for k in ("tension", "shear", "bearing")}
            if None in allow.values():
                allow = None
        lugs = Lugs(count=int(c.number(ld, "count", lp, integer=True, lo=1, hi=8) or 0),
                    orientation_start=c.angle(ld, "orientation_start", lp) or 0.0,
                    elevation=c.value(ld, "elevation", lp, L, positive=True) or 0.0,
                    thickness=c.value(ld, "thickness", lp, L, positive=True) or 0.0,
                    height=c.value(ld, "height", lp, L, positive=True) or 0.0,
                    projection=c.value(ld, "projection", lp, L, positive=True) or 0.0,
                    hole_diameter=c.value(ld, "hole_diameter", lp, L, positive=True) or 0.0,
                    hole_edge_distance=c.value(ld, "hole_edge_distance", lp, L, positive=True) or 0.0,
                    material=c.text(ld, "material", lp) or "", allowables=allow)
    if None in (orient, basis, D, tt, btl) or orient == "horizontal" or len(heads) != 2:
        return None
    return Geometry(orient, basis, D, tt, btl, courses, heads, nozzles, legs, lugs,
                    str(d.get("insulation", "none")))


def _base_plate(c: _Ctx, d: dict, path: str) -> dict:
    L = units.LENGTH
    out = {k: c.value(d, k, path, L, positive=True) for k in ("length", "width", "thickness")}
    out["anchor_holes"] = int(c.number(d, "anchor_holes", path, required=False, integer=True, lo=0, hi=8) or 0)
    out["anchor_hole_diameter"] = c.value(d, "anchor_hole_diameter", path, L, required=out["anchor_holes"] > 0,
                                          positive=True)
    out["anchor_spacing"] = c.value(d, "anchor_spacing", path, L, required=out["anchor_holes"] > 1, positive=True)
    out["anchor_bolt"] = str(d.get("anchor_bolt", ""))
    out["material"] = c.text(d, "material", path) or ""
    return out


def _loads(c: _Ctx, d: dict, geometry) -> dict[str, LoadItem]:
    out = {}
    for key in LOAD_KEYS:
        v = (d or {}).get(key)
        p = f"loads.{key}"
        if isinstance(v, dict) and "not_applicable" in v:
            reason = str(v["not_applicable"]).strip()
            if not reason:
                c.err(p, "not_applicable needs a reason")
            out[key] = LoadItem(key, False, reason, {}, "")
            continue
        if isinstance(v, str) and v.strip().lower() == "not_applicable":
            c.err(p, "write not_applicable as {not_applicable: '<reason>'}")
            continue
        if isinstance(v, dict) and v:
            vals = {}
            for k, raw in v.items():
                if k in ("basis", "note"):
                    continue
                if k == "impact_factor":
                    if isinstance(raw, (int, float)) and not isinstance(raw, bool) and raw >= 1.0:
                        vals[k] = float(raw)
                    else:
                        c.err(f"{p}.impact_factor", "must be a plain number >= 1.0")
                    continue
                dim = units.MOMENT if "moment" in k else units.FORCE
                try:
                    vals[k] = units.parse(raw, expect=dim, field=f"{p}.{k}").value
                except units.UnitError as exc:
                    c.err(f"{p}.{k}", str(exc))
            out[key] = LoadItem(key, True, None, vals, str(v.get("basis", "not stated")))
            if not v.get("basis"):
                c.warn(p, "load values given without a basis (standard, edition, calculation reference)")
            continue
        out[key] = LoadItem(key, False, None, {}, "")
        if key == "lifting":
            c.ask(p, "give the lifting impact factor (dynamic factor) and lifting method")
    return out


ASSESSMENT_OK = {"pass", "exempt", "acceptable", "impact_tested"}


def _assessments(c: _Ctx, d: dict) -> dict[str, dict]:
    """External engineering assessments for checks the software does not
    implement (e.g. UG-41 weld strength, support structure). Keyed by calc id."""
    out = {}
    if not isinstance(d, dict):
        c.err("assessments", "must map calc ids to assessment records")
        return out
    for cid, a in d.items():
        p = f"assessments.{cid}"
        if not isinstance(a, dict) or not {"result", "basis", "by", "status"} <= set(a):
            c.err(p, "an assessment needs result, basis, by and status")
            continue
        if str(a["status"]) not in DataStatus.__members__:
            c.err(f"{p}.status", f"unknown status {a['status']!r}")
            continue
        out[str(cid)] = {k: str(v) for k, v in a.items()}
    return out


def _external_data(c: _Ctx, d: dict, process) -> dict:
    out = {"shell": None, "heads": None}
    for key in ("shell", "heads"):
        v = d.get(key)
        p = f"external_pressure_data.{key}"
        if _is_none(v):
            continue          # the EXT-* records ask for the chart data with the ratios to enter
        if not isinstance(v, dict) or "source" not in v:
            c.err(p, "chart data needs at least 'source' plus A/B (and E for the elastic path)")
            continue
        rec = {"source": str(v["source"]), "status": str(v.get("status", "USER_SUPPLIED_UNVERIFIED"))}
        for k in ("A",):
            if k in v and v[k] is not None:
                rec[k] = float(v[k])
        for k in ("B", "E"):
            if k in v and v[k] is not None:
                rec[k] = units.parse(v[k], expect=units.PRESSURE, field=f"{p}.{k}").value
        rec["left_of_material_line"] = bool(v.get("left_of_material_line", False))
        out[key] = rec
    return out

"""Versioned material database with verification state.

Lookup policy (see references/material-data-policy.md):
* exact tabulated temperature -> tabulated value;
* between two tabulated temperatures -> linear interpolation, only if the
  record states ``interpolation: linear between tabulated temperatures`` (the
  convention of the Section II-D stress tables, to be confirmed by the user);
* outside the tabulated range -> refused (no extrapolation).
The result always carries the record's verification status, so a calculation
can tell whether its material data is release eligible.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from pathlib import Path

from .paths import DATA_DIR
from .status import DataStatus


class MaterialError(ValueError):
    pass


@dataclass
class MaterialRecord:
    id: str
    spec: str
    grade: str
    product_form: str
    temperatures: list[float]          # degC, ascending
    stresses: list[float]              # MPa
    interpolation: str = ""
    t_min: float | None = None
    t_max: float | None = None
    min_tensile: float | None = None   # MPa
    min_yield: float | None = None     # MPa
    density: float | None = None       # kg/m3
    source_document: str = ""
    table_reference: str = ""
    edition: str = ""
    verified_on: str | None = None
    verified_by: str | None = None
    status: DataStatus = DataStatus.UNVERIFIED
    notes: list[str] = field(default_factory=list)
    yield_at_temperature: dict | None = None   # optional {"temperature_degC": [...], "Sy_MPa": [...]}

    @property
    def name(self) -> str:
        return f"{self.spec} Gr {self.grade} ({self.product_form})".replace(" Gr -", "")

    def allowable_stress(self, temperature: float) -> tuple[float, str]:
        """(S in MPa, how it was obtained)."""
        return _lookup(self.temperatures, self.stresses, temperature, self.interpolation, self.id,
                       self.t_min, self.t_max)

    def yield_strength(self, temperature: float) -> tuple[float | None, str]:
        if self.yield_at_temperature:
            t = self.yield_at_temperature["temperature_degC"]
            s = self.yield_at_temperature["Sy_MPa"]
            return _lookup(t, s, temperature, self.interpolation, self.id, t[0], t[-1])
        return None, "no yield-vs-temperature data in the record"

    def to_dict(self) -> dict:
        return {"id": self.id, "name": self.name, "spec": self.spec, "grade": self.grade,
                "product_form": self.product_form, "status": str(self.status),
                "source_document": self.source_document, "table_reference": self.table_reference,
                "edition": self.edition, "verified_on": self.verified_on, "verified_by": self.verified_by,
                "density_kg_m3": self.density, "min_tensile_MPa": self.min_tensile,
                "min_yield_MPa": self.min_yield, "notes": self.notes}


def _lookup(ts, ss, T, interpolation, rid, t_min, t_max):
    if len(ts) != len(ss) or not ts:
        raise MaterialError(f"{rid}: temperature and stress lists differ in length or are empty")
    lo_lim = ts[0] if t_min is None else t_min
    hi_lim = ts[-1] if t_max is None else t_max
    if T < lo_lim - 1e-9 or T > hi_lim + 1e-9 or T < ts[0] - 1e-9 or T > ts[-1] + 1e-9:
        raise MaterialError(f"{rid}: {T:g} degC is outside the tabulated range "
                            f"{ts[0]:g}..{ts[-1]:g} degC; no extrapolation is performed")
    for t, s in zip(ts, ss):
        if abs(t - T) < 1e-9:
            return s, f"tabulated value at {t:g} degC"
    for (t0, s0), (t1, s1) in zip(zip(ts, ss), zip(ts[1:], ss[1:])):
        if t0 < T < t1:
            if "linear" not in (interpolation or "").lower():
                raise MaterialError(f"{rid}: {T:g} degC lies between tabulated points and the record "
                                    "does not permit interpolation")
            s = s0 + (s1 - s0) * (T - t0) / (t1 - t0)
            return s, f"linear interpolation between {t0:g} degC ({s0:g}) and {t1:g} degC ({s1:g})"
    raise MaterialError(f"{rid}: lookup failed at {T:g} degC")


def record_from_dict(d: dict) -> MaterialRecord:
    st = d.get("allowable_stress") or {}
    temps = [float(x) for x in st.get("temperature_degC", [])]
    stresses = [float(x) for x in st.get("S_MPa", [])]
    if temps != sorted(temps):
        raise MaterialError(f"{d.get('id')}: temperatures must be ascending")
    lim = d.get("temperature_limits_degC") or {}
    try:
        status = DataStatus(d.get("verification_status", "UNVERIFIED"))
    except ValueError:
        raise MaterialError(f"{d.get('id')}: unknown verification_status {d.get('verification_status')!r}") from None
    if status.release_eligible and not (d.get("verified_by") and d.get("verified_on") and d.get("source_document")):
        raise MaterialError(f"{d.get('id')}: status {status} needs verified_by, verified_on and source_document")
    return MaterialRecord(
        id=d["id"], spec=d["spec"], grade=str(d.get("grade", "-")), product_form=d.get("product_form", ""),
        temperatures=temps, stresses=stresses, interpolation=d.get("interpolation", ""),
        t_min=lim.get("min"), t_max=lim.get("max"), min_tensile=d.get("min_tensile_MPa"),
        min_yield=d.get("min_yield_MPa"), density=d.get("density_kg_m3"),
        source_document=d.get("source_document", ""), table_reference=d.get("table_reference", ""),
        edition=str(d.get("edition", "")), verified_on=d.get("verified_on"), verified_by=d.get("verified_by"),
        status=status, notes=list(d.get("notes", [])), yield_at_temperature=d.get("yield_at_temperature"))


class MaterialDatabase:
    def __init__(self, records: dict[str, MaterialRecord], version: str, path: str = ""):
        self.records, self.version, self.path = records, version, path

    @classmethod
    def load(cls, path: Path | None = None) -> "MaterialDatabase":
        p = Path(path or DATA_DIR / "materials" / "material_db.json")
        data = json.loads(p.read_text(encoding="utf-8"))
        recs = {}
        for d in data["records"]:
            r = record_from_dict(d)
            if r.id in recs:
                raise MaterialError(f"duplicate material id {r.id}")
            recs[r.id] = r
        return cls(recs, data.get("db_version", "?"), str(p))

    def add(self, rec: MaterialRecord, *, replace: bool = False):
        if rec.id in self.records and not replace:
            raise MaterialError(f"material id {rec.id} already exists")
        self.records[rec.id] = rec

    def get(self, mid: str) -> MaterialRecord:
        if mid not in self.records:
            raise MaterialError(f"material {mid!r} not found in database {self.version}; "
                                f"known ids: {sorted(self.records)}")
        return self.records[mid]

"""Pipe outside diameters and walls (B36.10M subset, UNVERIFIED data)."""

from __future__ import annotations

import json
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

from .paths import DATA_DIR


@dataclass(frozen=True)
class PipeSize:
    nps: str
    schedule: str
    od: float        # mm
    wall: float      # mm, nominal
    std_wall: float  # mm, standard weight wall of this NPS
    source: str
    status: str


def _norm_nps(nps) -> str:
    s = str(nps).strip().replace('"', "").replace(" ", "-")
    aliases = {"0.5": "1/2", "0.75": "3/4", "1.5": "1-1/2", "1.0": "1"}
    if s in aliases:
        return aliases[s]
    try:
        f = float(s)
        if f == int(f):
            return str(int(f))
    except ValueError:
        pass
    return s


@lru_cache(maxsize=4)
def _table(path: str):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def lookup(nps, schedule, path: Path | None = None) -> PipeSize:
    data = _table(str(path or DATA_DIR / "pipe" / "pipe_dimensions.json"))
    key = _norm_nps(nps)
    sch = str(schedule).strip().upper().replace("SCH", "").strip()
    for row in data["rows"]:
        if row["nps"] == key:
            walls = row["walls_in"]
            if sch not in walls:
                raise KeyError(f"NPS {key}: schedule {schedule!r} not in table (have {sorted(walls)})")
            return PipeSize(key, sch, row["od_in"] * 25.4, walls[sch] * 25.4, walls["STD"] * 25.4,
                            data["source_document"], data["verification_status"])
    raise KeyError(f"NPS {nps!r} not in pipe table")


def ug45_table_value(nps, path: Path | None = None) -> tuple[float, str]:
    """Table UG-45 thickness as derived from the standard-weight wall:
    0.875 x STD wall, with NPS 12 and larger capped at the NPS 12 STD value
    (STD wall is 0.375 in for all of them in the table, so the cap is implicit).
    The derivation must be confirmed against the licensed Table UG-45."""
    p = lookup(nps, "STD", path)
    return 0.875 * p.std_wall, f"0.875 x STD wall {p.std_wall:.2f} mm of NPS {p.nps} (derived; UNVERIFIED)"

"""Code reference register with per-project verification state."""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path

from .paths import DATA_DIR


@dataclass
class CodeReference:
    id: str
    family: str
    document: str
    clause: str
    title: str
    used_for: str = ""
    edition_basis: str = ""
    cited_by: str = ""
    verification_status: str = "UNVERIFIED"
    verified_by: str | None = None
    verified_on: str | None = None
    verified_edition: str | None = None
    remark: str = ""

    @property
    def verified(self) -> bool:
        return self.verification_status == "VERIFIED"

    def label(self) -> str:
        return f"{self.document.replace('ASME BPVC Section VIII Division 1', 'ASME VIII-1')} {self.clause}"


class ReferenceRegister:
    def __init__(self, entries: dict[str, CodeReference], version: str):
        self.entries = entries
        self.version = version

    @classmethod
    def load(cls, path: Path | None = None, verification: dict | list | None = None) -> "ReferenceRegister":
        data = json.loads(Path(path or DATA_DIR / "code_references.json").read_text(encoding="utf-8"))
        entries = {}
        for e in data["entries"]:
            known = {k: v for k, v in e.items() if k in CodeReference.__dataclass_fields__}
            entries[e["id"]] = CodeReference(**known)
        reg = cls(entries, data.get("register_version", "?"))
        if verification:
            reg.apply_verification(verification)
        return reg

    def apply_verification(self, items) -> list[str]:
        """Mark entries verified from a project file. Each item needs id,
        verified_by, verified_on and edition; anything incomplete is refused."""
        if isinstance(items, dict):
            items = items.get("verified", [])
        problems = []
        for it in items or []:
            rid = it.get("id")
            if rid not in self.entries:
                problems.append(f"unknown reference id {rid!r}")
                continue
            missing = [k for k in ("verified_by", "verified_on", "edition") if not it.get(k)]
            if missing:
                problems.append(f"{rid}: verification needs {missing}")
                continue
            ref = self.entries[rid]
            ref.verification_status = "VERIFIED"
            ref.verified_by, ref.verified_on = str(it["verified_by"]), str(it["verified_on"])
            ref.verified_edition = str(it["edition"])
            ref.remark = str(it.get("remark", ""))
        return problems

    def get(self, rid: str) -> CodeReference:
        if rid not in self.entries:
            raise KeyError(f"code reference {rid!r} is not in the register; add it before citing it")
        return self.entries[rid]

    def unverified(self, ids) -> list[str]:
        return [f"code reference {rid} not verified" for rid in ids if not self.get(rid).verified]

    def summary(self, used_ids) -> dict:
        used = sorted(set(used_ids))
        return {"register_version": self.version, "used": len(used),
                "verified": sum(self.get(r).verified for r in used),
                "unverified_ids": [r for r in used if not self.get(r).verified]}

"""Explicit-unit quantities.

Every dimensional input must state its unit: ``"1.0 MPa"``, ``"8 mm"``,
``"-10 degC"`` or ``{value: 1.0, unit: MPa}``. A bare number for a dimensional
field is rejected, so MPa can never be mixed with psi, or mm with inch,
without an explicit conversion.

Internal (calculation) units: length mm, area mm^2, volume mm^3, pressure and
stress MPa (= N/mm^2), force N, moment N*mm, mass kg, density kg/m^3,
temperature degC, fractions as plain numbers (12.5 % -> 0.125).
"""

from __future__ import annotations

import math
import re
from dataclasses import dataclass

LENGTH, AREA, VOLUME, PRESSURE, TEMPERATURE = "length", "area", "volume", "pressure", "temperature"
DENSITY, MASS, FORCE, MOMENT, FRACTION, ACCEL = "density", "mass", "force", "moment", "fraction", "acceleration"

_PSI = 0.006894757293168361  # MPa per psi (exact from lbf and inch definitions)

# unit text (lower case, normalised) -> (dimension, factor to internal unit)
_LINEAR: dict[str, tuple[str, float]] = {
    "mm": (LENGTH, 1.0), "m": (LENGTH, 1000.0), "cm": (LENGTH, 10.0),
    "in": (LENGTH, 25.4), "inch": (LENGTH, 25.4), "ft": (LENGTH, 304.8),
    "mm2": (AREA, 1.0), "cm2": (AREA, 100.0), "m2": (AREA, 1.0e6), "in2": (AREA, 645.16),
    "mm3": (VOLUME, 1.0), "cm3": (VOLUME, 1.0e3), "m3": (VOLUME, 1.0e9), "l": (VOLUME, 1.0e6),
    "in3": (VOLUME, 16387.064), "ft3": (VOLUME, 28316846.592), "usgal": (VOLUME, 3785411.784),
    "mpa": (PRESSURE, 1.0), "n/mm2": (PRESSURE, 1.0), "kpa": (PRESSURE, 1.0e-3),
    "pa": (PRESSURE, 1.0e-6), "bar": (PRESSURE, 0.1), "psi": (PRESSURE, _PSI),
    "ksi": (PRESSURE, _PSI * 1000.0), "kgf/cm2": (PRESSURE, 0.0980665),
    "kg/m3": (DENSITY, 1.0), "g/cm3": (DENSITY, 1000.0), "lb/ft3": (DENSITY, 16.018463373960138),
    "kg": (MASS, 1.0), "t": (MASS, 1000.0), "lb": (MASS, 0.45359237),
    "n": (FORCE, 1.0), "kn": (FORCE, 1.0e3), "lbf": (FORCE, 4.4482216152605), "kgf": (FORCE, 9.80665),
    "n.mm": (MOMENT, 1.0), "n.m": (MOMENT, 1.0e3), "kn.m": (MOMENT, 1.0e6),
    "lbf.ft": (MOMENT, 1355.8179483314004), "lbf.in": (MOMENT, 112.98482902761670),
    "%": (FRACTION, 0.01), "fraction": (FRACTION, 1.0),
    "m/s2": (ACCEL, 1000.0), "mm/s2": (ACCEL, 1.0), "g0": (ACCEL, 9806.65),
}
_TEMPS = {"degc": "C", "c": "C", "°c": "C", "degf": "F", "f": "F", "°f": "F", "k": "K"}

# gauge / absolute suffixes on pressure units: "MPa(g)", "barg", "psig", "psia"
_GAUGE_RE = re.compile(r"^(?P<u>[a-z/0-9]+?)\s*(?:\((?P<p>[ga])\)|(?P<s>[ga]))$")

INTERNAL_UNIT = {LENGTH: "mm", AREA: "mm2", VOLUME: "mm3", PRESSURE: "MPa", TEMPERATURE: "degC",
                 DENSITY: "kg/m3", MASS: "kg", FORCE: "N", MOMENT: "N.mm", FRACTION: "-",
                 ACCEL: "mm/s2"}

G0 = 9806.65  # standard gravity, mm/s^2


class UnitError(ValueError):
    """Raised for a missing, unknown or dimensionally wrong unit."""


def _norm(unit: str) -> str:
    u = unit.strip().lower().replace(" ", "").replace("·", ".").replace("*", ".")
    u = u.replace("²", "2").replace("³", "3").replace("^", "")
    return {"n/m2": "pa", "mpa(g)": "mpa(g)", "litre": "l", "liter": "l"}.get(u, u)


@dataclass(frozen=True)
class Quantity:
    """A value converted to the internal unit of its dimension."""

    value: float
    dim: str
    text: str = ""          # the original input text, kept for the report
    pressure_ref: str = ""  # "g", "a" or "" for pressures

    @property
    def unit(self) -> str:
        return INTERNAL_UNIT[self.dim]

    def __float__(self) -> float:
        return self.value


def _split(text: str) -> tuple[float, str]:
    m = re.match(r"^\s*([-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?)\s*(.*?)\s*$", text)
    if not m:
        raise UnitError(f"cannot read a number and unit from {text!r}")
    return float(m.group(1)), m.group(2)


def convert(value: float, unit: str, *, expect: str | None = None) -> Quantity:
    """Convert ``value`` given in ``unit`` to the internal unit."""
    if not isinstance(value, (int, float)) or isinstance(value, bool) or not math.isfinite(value):
        raise UnitError(f"value must be a finite number, got {value!r}")
    u = _norm(unit)
    text = f"{value:g} {unit}"
    if u in _TEMPS:
        kind = _TEMPS[u]
        c = value if kind == "C" else (value - 32.0) * 5.0 / 9.0 if kind == "F" else value - 273.15
        q = Quantity(c, TEMPERATURE, text)
    else:
        ref = ""
        if u not in _LINEAR:
            m = _GAUGE_RE.match(u)
            if m and m.group("u") in _LINEAR and _LINEAR[m.group("u")][0] == PRESSURE:
                ref = m.group("p") or m.group("s")
                u = m.group("u")
        if u not in _LINEAR:
            raise UnitError(f"unknown unit {unit!r}")
        dim, factor = _LINEAR[u]
        q = Quantity(value * factor, dim, text, ref)
    if expect is not None and q.dim != expect:
        raise UnitError(f"{text!r} is a {q.dim}, expected a {expect}")
    return q


def parse(raw, *, expect: str | None = None, field: str = "value") -> Quantity:
    """Parse ``"8 mm"`` or ``{value: 8, unit: mm}``. Bare numbers are rejected
    unless ``expect`` is None-dimensional (handled by callers)."""
    if isinstance(raw, Quantity):
        if expect and raw.dim != expect:
            raise UnitError(f"{field}: {raw.text!r} is a {raw.dim}, expected a {expect}")
        return raw
    if isinstance(raw, bool) or raw is None:
        raise UnitError(f"{field}: a quantity with a unit is required, got {raw!r}")
    if isinstance(raw, (int, float)):
        raise UnitError(f"{field}: {raw!r} has no unit; write it as e.g. '{raw} "
                        f"{INTERNAL_UNIT.get(expect or '', 'mm')}'")
    if isinstance(raw, dict):
        if set(raw) - {"value", "unit", "source", "note"} or "value" not in raw or "unit" not in raw:
            raise UnitError(f"{field}: a quantity mapping needs exactly 'value' and 'unit' "
                            f"(optional 'source', 'note'), got keys {sorted(raw)}")
        try:
            return convert(raw["value"], str(raw["unit"]), expect=expect)
        except UnitError as exc:
            raise UnitError(f"{field}: {exc}") from None
    if isinstance(raw, str):
        try:
            v, u = _split(raw)
            if not u:
                raise UnitError(f"{raw!r} has no unit")
            return convert(v, u, expect=expect)
        except UnitError as exc:
            raise UnitError(f"{field}: {exc}") from None
    raise UnitError(f"{field}: cannot interpret {raw!r} as a quantity")


def to(value: float, dim: str, unit: str) -> float:
    """Convert an internal value to a display unit (inverse of convert)."""
    u = _norm(unit)
    if dim == TEMPERATURE:
        kind = _TEMPS[u]
        return value if kind == "C" else value * 9.0 / 5.0 + 32.0 if kind == "F" else value + 273.15
    d, factor = _LINEAR[u]
    if d != dim:
        raise UnitError(f"cannot express a {dim} in {unit}")
    return value / factor


def fmt(value: float | None, digits: int = 3) -> str:
    """Engineering formatting used in reports: fixed decimals, no exponent for
    ordinary magnitudes."""
    if value is None:
        return "—"
    if value != 0 and (abs(value) >= 1e7 or abs(value) < 10 ** (-digits)):
        return f"{value:.{digits}e}"
    return f"{value:.{digits}f}"

"""Independent formulations used to cross-check the calculation engine.

Nothing here calls the engine's formula functions. The checks use either a
different equation (outside-dimension forms of Mandatory Appendix 1-1/1-4,
which are algebraically equivalent when Ro = R + t), a different numerical
route (bisection on the stress equation instead of the closed form), or a
different geometric derivation (reinforcement areas from the limits of
reinforcement; head volumes from spherical-zone and torus formulas).
"""

from __future__ import annotations

import math


def bisect(f, lo, hi, tol=1e-12, it=300):
    flo = f(lo)
    for _ in range(it):
        mid = 0.5 * (lo + hi)
        fm = f(mid)
        if (fm > 0) == (flo > 0):
            lo, flo = mid, fm
        else:
            hi = mid
        if hi - lo < tol:
            break
    return 0.5 * (lo + hi)


# --- shells -----------------------------------------------------------------

def shell_circ_by_stress(P, R, S, E):
    """Thickness where the UG-27 circumferential stress P(R + 0.6t)/(Et) = S."""
    return bisect(lambda t: P * (R + 0.6 * t) / (E * t) - S, 1e-9, R)


def shell_long_by_stress(P, R, S, E):
    """Thickness where the longitudinal stress P(R - 0.4t)/(2Et) = S."""
    return bisect(lambda t: P * (R - 0.4 * t) / (2 * E * t) - S, 1e-9, R)


def shell_circ_outside_form(P, R, S, E):
    """Appendix 1-1 outside-radius form t = P Ro/(SE + 0.4P), Ro = R + t,
    solved by fixed-point iteration."""
    t = 0.0
    for _ in range(200):
        t = P * (R + t) / (S * E + 0.4 * P)
    return t


def shell_long_outside_form(P, R, S, E):
    t = 0.0
    for _ in range(200):
        t = P * (R + t) / (2 * S * E + 1.4 * P)
    return t


def lame_hoop_max(P, Ri, t):
    """Exact elastic hoop stress at the bore of a thick cylinder (information)."""
    Ro = Ri + t
    return P * (Ro ** 2 + Ri ** 2) / (Ro ** 2 - Ri ** 2)


# --- heads ------------------------------------------------------------------------

def ellipsoidal_outside_form(P, D, S, E, ar):
    K = (2 + ar * ar) / 6.0
    t = 0.0
    for _ in range(200):
        t = P * (D + 2 * t) * K / (2 * S * E + 2 * P * (K - 0.1))
    return t


def torispherical_outside_form(P, L, r, S, E):
    M = 0.25 * (3 + math.sqrt(L / r))
    t = 0.0
    for _ in range(200):
        t = P * (L + t) * M / (2 * S * E + P * (M - 0.2))
    return t


def hemispherical_outside_form(P, L, S, E):
    t = 0.0
    for _ in range(200):
        t = P * (L + t) / (2 * S * E + 0.8 * P)
    return t


def head_stress_at_mawp(kind, P, D, t, E, ar=2.0, L=None, r=None):
    """Membrane stress S implied by (P, t): should equal the allowable stress
    when P is the MAWP."""
    if kind == "ellipsoidal":
        K = (2 + ar * ar) / 6.0
        return P * (K * D + 0.2 * t) / (2 * E * t)
    if kind == "torispherical":
        M = 0.25 * (3 + math.sqrt(L / r))
        return P * (L * M + 0.2 * t) / (2 * E * t)
    return P * (D / 2 + 0.2 * t) / (2 * E * t)


# --- reinforcement (geometric derivation) -----------------------------------------

def area_geometric(d, t, tr, tn, trn, Sv, Sn, Sp=None, te=0.0, Dp=0.0, inserted=True):
    """Area bookkeeping derived from the reinforcement zone instead of the
    printed formulas: the zone is 2*Lp wide (parallel limit) and Ln high
    (normal limit) on each side of the wall; excess metal inside the zone,
    weighted by the strength ratio, is available. Welds are not counted."""
    f2 = min(Sn / Sv, 1.0)
    f1 = f2 if inserted else 1.0
    pad = te > 0 and Dp > 0
    f4 = min((Sp or Sv) / Sv, 1.0) if pad else 1.0
    Lp = max(d, d / 2 + tn + t)
    Ln = min(2.5 * t, 2.5 * tn + te)
    excess = t - tr
    shell_band = (2 * Lp - d) * excess                    # shell strip inside the zone minus the hole
    shell_band -= 2 * tn * excess * (1 - f1)             # nozzle wall replaces shell metal at fr1
    nozzle = 2 * Ln * (tn - trn) * f2 if tn > trn else 0.0
    pad_area = (min(Dp, 2 * Lp) - d - 2 * tn) * min(te, Ln) * f4 if pad else 0.0
    required = d * tr + 2 * tn * tr * (1 - f1)
    return {"A": required, "A1": max(shell_band, 0.0), "A2": nozzle, "A5": max(pad_area, 0.0),
            "A_avail": max(shell_band, 0.0) + nozzle + max(pad_area, 0.0)}


# --- volumes (closed forms) ---------------------------------------------------------

def hemisphere_metal(a, t):
    return 2.0 / 3.0 * math.pi * ((a + t) ** 3 - a ** 3)


def torispherical_solid(a, L, r):
    """Closed-form volume of the solid bounded by the torispherical surface
    and the tangent plane: torus-section knuckle (Pappus) + spherical crown
    segment + the cylinder under the crown base."""
    yc = -math.sqrt((L - r) ** 2 - (a - r) ** 2)
    beta = math.acos((a - r) / (L - r))
    # knuckle: region between rho = 0 and the arc for y in [0, r sin(beta)]
    yk = r * math.sin(beta)
    c = a - r
    # pi * integral_0^yk (c + sqrt(r^2 - y^2))^2 dy, in closed form
    root = math.sqrt(r * r - yk * yk)
    Vk = math.pi * ((c * c + r * r) * yk - yk ** 3 / 3.0 + c * (yk * root + r * r * math.asin(yk / r)))
    # crown: spherical cap above y = yk of the sphere centred at yc with radius L
    cap_h = (yc + L) - yk
    Vc = math.pi * cap_h ** 2 * (3 * L - cap_h) / 3.0
    return Vk + Vc


def ellipsoid_half(a, b):
    return 2.0 / 3.0 * math.pi * a * a * b

"""Verification runner: independent re-computation of the actual results,
benchmark suites, and the PV Elite comparison harness.

A discrepancy stops release (gate) and is reported; nothing is adjusted to
make results agree.
"""

from __future__ import annotations

import csv
import json
import math
from pathlib import Path

from ..codes.api_650.design import one_foot_td, one_foot_tt
from ..codes.asme_viii_1 import formulas as F
from ..codes.asme_viii_1.context import hydrostatic
from ..geometry import profiles as pf
from ..paths import DATA_DIR
from ..status import Status
from . import independent as I

PSI = 0.006894757293168361
IN = 25.4


def _close(a, b, rel=1e-6, abs_=1e-9):
    return a is not None and b is not None and abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))


class _Log:
    def __init__(self):
        self.items = []

    def check(self, group, cid, quantity, engine, independent, rel=1e-6, note="", method=""):
        ok = _close(engine, independent, rel)
        self.items.append({"group": group, "id": cid, "quantity": quantity, "engine": engine,
                           "independent": independent, "rel_tol": rel, "ok": ok, "method": method, "note": note})
        return ok


def _tv(rec, sym):
    for grp in ("results", "intermediates", "inputs"):
        for tv in rec[grp]:
            if tv["symbol"] == sym:
                return tv["value"]
    return None


def verify_results(results: dict, geometry: dict | None, log: _Log):
    """Re-compute the engine's own results with independent formulations."""
    for r in results["records"]:
        cid = r["calc_id"]
        if cid.startswith("SH-") and not cid.endswith("MAWP") and _tv(r, "t_circ") is not None:
            P, R, S = _tv(r, "P"), _tv(r, "R"), _tv(r, "S")
            El, Ec = _tv(r, "E_long"), _tv(r, "E_circ")
            log.check("shell", cid, "t_circ", _tv(r, "t_circ"), I.shell_circ_by_stress(P, R, S, El), 1e-7,
                      method="bisection on P(R+0.6t)/(Et) = S")
            log.check("shell", cid, "t_circ", _tv(r, "t_circ"), I.shell_circ_outside_form(P, R, S, El), 1e-7,
                      method="Appendix 1-1 outside-radius form")
            log.check("shell", cid, "t_long", _tv(r, "t_long"), I.shell_long_by_stress(P, R, S, Ec), 1e-7,
                      method="bisection on P(R-0.4t)/(2Et) = S")
            log.check("shell", cid, "t_long", _tv(r, "t_long"), I.shell_long_outside_form(P, R, S, Ec), 1e-7,
                      method="Appendix 1-1 outside-radius form (longitudinal)")
        if cid.startswith("SH-") and cid.endswith("-MAWP") and _tv(r, "P_circ") is not None:
            base = next(x for x in results["records"] if x["calc_id"] == cid[:-5])
            S, El = _tv(base, "S"), _tv(base, "E_long")
            t, R = _tv(r, "t"), _tv(r, "R")
            sig = _tv(r, "P_circ") * (R + 0.6 * t) / (El * t)
            log.check("shell", cid, "stress at MAWP", sig, S, 1e-9, method="stress equation evaluated at MAWP")
        if cid.startswith("HD-") and cid.count("-") == 1 and _tv(r, "t_req") is not None:
            P, S, E, Dc = _tv(r, "P"), _tv(r, "S"), _tv(r, "E"), _tv(r, "D_c")
            if _tv(r, "K") is not None:
                K = _tv(r, "K")
                ar = math.sqrt(6 * K - 2)
                ind = I.ellipsoidal_outside_form(P, Dc, S, E, ar)
                m = "Appendix 1-4(c) outside-diameter form"
            elif _tv(r, "M") is not None:
                ind = I.torispherical_outside_form(P, _tv(r, "L"), _tv(r, "r"), S, E)
                m = "Appendix 1-4(d) outside-radius form"
            else:
                ind = I.hemispherical_outside_form(P, _tv(r, "L"), S, E)
                m = "outside-radius form (sphere)"
            log.check("head", cid, "t_req", _tv(r, "t_req"), ind, 1e-7, method=m)
        if cid.endswith("-UG37") and _tv(r, "A") is not None:
            ia = I.area_geometric(_tv(r, "d"), _tv(r, "t"), _tv(r, "tr"), _tv(r, "tn"), _tv(r, "trn"),
                                  _tv(r, "Sv"), _tv(r, "Sn"), _tv(r, "Sp"), _tv(r, "te") or 0.0,
                                  _tv(r, "Dp") or 0.0, inserted=_tv(r, "attachment") == "set_in")
            for q in ("A", "A1", "A2", "A5"):
                log.check("nozzle", cid, q, _tv(r, q), ia[q], 1e-9, method="reinforcement-zone derivation")
        if cid == "MAWP" and _tv(r, "MAWP") is not None:
            parts = [tv["value"] for tv in r["intermediates"] if tv["symbol"].startswith("MAWP[")]
            log.check("vessel", cid, "MAWP", _tv(r, "MAWP"), min(parts), 1e-12, method="minimum of part MAWPs")
        if cid == "TEST-P" and _tv(r, "P_test_top") is not None:
            f = 1.3 if "hydro" in r["title"].lower() else 1.1
            log.check("vessel", cid, "P_test_top", _tv(r, "P_test_top"), f * _tv(r, "P_basis") * _tv(r, "LSR"), 1e-12,
                      method="hand formula")
    if geometry:
        a = geometry["vessel"]["inside_diameter"] / 2
        for c in geometry["components"]:
            if c["kind"] == "shell_course" and not c["params"].get("openings"):
                t, L = c["params"]["thickness"], c["params"]["length"]
                log.check("geometry", c["tag"], "volume", c["volume_mm3"], math.pi * ((a + t) ** 2 - a * a) * L, 1e-9,
                          method="ring volume")
        log.check("geometry", "capacity", "internal volume", geometry["vessel"]["internal_volume_mm3"],
                  _capacity_closed_form(geometry), 1e-5, method="closed-form head volumes + cylinder")


def _capacity_closed_form(geometry):
    a = geometry["vessel"]["inside_diameter"] / 2
    total = math.pi * a * a * sum(c["params"]["length"] for c in geometry["components"] if c["kind"] == "shell_course")
    for c in geometry["components"]:
        if c["kind"] != "head":
            continue
        p = c["params"]
        if p["type"] == "ellipsoidal":
            total += I.ellipsoid_half(a, a / p["aspect_ratio"])
        elif p["type"] == "hemispherical":
            total += 2 / 3 * math.pi * a ** 3
        else:
            total += I.torispherical_solid(a, p["crown_radius"], p["knuckle_radius"])
        total += math.pi * a * a * p["straight_flange"]
    return total


# --- benchmark suites ---------------------------------------------------------------

def _call(fn, i):
    if fn == "area_replacement":
        return F.area_replacement(**i)
    if fn == "hydro":
        return i["factor"] * i["mawp"] * i["lsr"]
    if fn == "api650_td":
        return one_foot_td(i["D_m"], i["H_m"], i["G"], i["Sd"], i["CA"])
    if fn == "api650_tt":
        return one_foot_tt(i["D_m"], i["H_m"], i["St"])
    if fn == "hydrostatic":
        return hydrostatic(i["height_mm"], i["density_kg_m3"])
    if fn == "head_metal_volume":
        return pf.head_metal(pf.HeadProfile(i["kind"], i["a"]), i["t"], i["sf"])[0]
    if fn == "head_capacity":
        return pf.head_capacity(pf.HeadProfile(i["kind"], i["a"], i.get("ar", 2.0)), i["sf"])
    return getattr(F, fn)(**i)


def run_benchmarks(log: _Log, path: Path | None = None):
    bdir = Path(path or DATA_DIR / "benchmarks")
    hand = json.loads((bdir / "hand_calcs_si.json").read_text(encoding="utf-8"))
    for c in hand["cases"]:
        out = _call(c["function"], c["inputs"])
        for k, exp in c["expected"].items():
            got = out[k] if isinstance(out, dict) else out
            log.check("benchmark:hand", c["id"], f"{c['title']} [{k}]", got, exp, c["tolerance_rel"],
                      method=c["function"], note=c["arithmetic"][:160])
    lz = json.loads((bdir / "laela_zorana_us_units.json").read_text(encoding="utf-8"))
    for c in lz["cases"]:
        i = c["inputs_us"]
        fn = c["function"]
        if fn == "shell_t_circ":
            got = F.shell_t_circ(i["P_psi"] * PSI, i["R_in"] * IN, i["S_psi"] * PSI, i["E"]) / IN
        elif fn == "ellipsoidal_t":
            got = F.ellipsoidal_t(i["P_psi"] * PSI, i["D_in"] * IN, i["S_psi"] * PSI, i["E"]) / IN
        elif fn == "shell_mawp_circ":
            got = F.shell_mawp_circ(i["t_in"] * IN, i["R_in"] * IN, i["S_psi"] * PSI, i["E"]) / PSI
        elif fn == "torispherical_t":
            got = F.torispherical_t(i["P_psi"] * PSI, i["L_in"] * IN, i["r_in"] * IN, i["S_psi"] * PSI, i["E"]) / IN
        else:   # area_A_us with the reference library's convention, plus ours for the record
            P, R, S, Sn = i["P_psi"] * PSI, i["R_in"] * IN, i["S_psi"] * PSI, i["Sn_psi"] * PSI
            CA, tw, OD = i["CA_in"] * IN, i["tw_in"] * IN, i["OD_in"] * IN
            tr = F.shell_t_circ(P, R, S, 1.0)
            tn_ref = tw * (1 - i["mill_tol"]) - CA
            d_ref = OD - 2 * tn_ref
            trn = F.shell_t_circ(P, d_ref / 2, Sn, 1.0)
            got = F.area_replacement(d=d_ref, t=0.5 * IN, tr=tr, tn=tn_ref, trn=trn, Sv=S, Sn=Sn)["A"] / IN ** 2
            tn = tw - CA
            d = OD - 2 * tw + 2 * CA
            ours = F.area_replacement(d=d, t=0.5 * IN, tr=tr, tn=tn, trn=F.shell_t_circ(P, d / 2, Sn, 1.0),
                                      Sv=S, Sn=Sn)["A"] / IN ** 2
            log.items.append({"group": "benchmark:cross-implementation", "id": c["id"] + "-default-convention",
                              "quantity": "A with UG-16(d) convention (in2)", "engine": ours,
                              "independent": c["expected_us"]["value_in2"], "rel_tol": None, "ok": True,
                              "method": "information: known method difference", "note": c["method_difference"]})
        exp = next(iter(c["expected_us"].values()))
        log.check("benchmark:cross-implementation", c["id"], c["title"], got, exp, c["tolerance_rel"],
                  method=fn, note=c["method_difference"] or lz["source"][:120])


# --- PV Elite comparison --------------------------------------------------------------

def compare_pv_elite(results: dict, csv_path: Path | None, log: _Log) -> dict:
    """CSV columns: calc_id, symbol, value, unit, rel_tolerance. Values must be
    in the engine's units (mm, MPa, mm2). Returns a status block."""
    if not csv_path or not Path(csv_path).is_file():
        return {"status": "NOT_AVAILABLE", "note": "no PV Elite results supplied; harness ready "
                                                   "(examples/pv_elite_results_template.csv)"}
    recs = {r["calc_id"]: r for r in results["records"]}
    n = bad = 0
    with open(csv_path, newline="", encoding="utf-8") as fh:
        for row in csv.DictReader(fh):
            if not row.get("calc_id") or row["calc_id"].lstrip().startswith("#"):
                continue
            r = recs.get(row["calc_id"])
            eng = _tv(r, row["symbol"]) if r else None
            ok = log.check("pv_elite", row["calc_id"], row["symbol"], eng, float(row["value"]),
                           float(row.get("rel_tolerance") or 0.005), method="PV Elite (user-supplied)")
            n += 1
            bad += 0 if ok else 1
    return {"status": "COMPARED", "values": n, "deviations": bad, "file": str(csv_path)}


def run_verification(results: dict, geometry: dict | None, pv_elite_csv=None) -> dict:
    log = _Log()
    verify_results(results, geometry, log)
    run_benchmarks(log)
    pve = compare_pv_elite(results, pv_elite_csv, log)
    failed = [i for i in log.items if not i["ok"]]
    return {"schema": "pv-design/verification@1", "results_hash": results["results_hash"],
            "input_hash": results["input_hash"], "passed": not failed, "n_checks": len(log.items),
            "n_failed": len(failed), "items": log.items, "discrepancies": failed, "pv_elite": pve,
            "scope_note": "Verifies the implementation (arithmetic, algebra, geometry) against independent "
                          "formulations and benchmarks. It does not verify the Code formulas themselves; "
                          "that needs the licensed Code (reference register)."}


def verification_markdown(v: dict) -> str:
    lines = [f"# Verification report", "",
             f"- Result set: `{v['results_hash'][:16]}` (input `{v['input_hash'][:16]}`)",
             f"- Checks: {v['n_checks']}, failed: {v['n_failed']} -> **{'PASSED' if v['passed'] else 'DISCREPANCIES'}**",
             f"- PV Elite comparison: {v['pv_elite']['status']} — {v['pv_elite'].get('note', '')}",
             f"- Scope: {v['scope_note']}", "",
             "| Group | Id | Quantity | Engine | Independent | Rel. tol | OK | Method |", "|---|---|---|---|---|---|---|---|"]
    for i in v["items"]:
        e = i["engine"]
        x = i["independent"]
        fmt = (lambda z: f"{z:.6g}" if isinstance(z, (int, float)) else str(z))
        lines.append(f"| {i['group']} | {i['id']} | {i['quantity']} | {fmt(e)} | {fmt(x)} | "
                     f"{i['rel_tol'] if i['rel_tol'] is not None else 'info'} | {'yes' if i['ok'] else '**NO**'} | {i['method']} |")
    notes = [i for i in v["items"] if i.get("note") and "method" in str(i.get("method")) and "difference" in str(i.get("note"))]
    if notes:
        lines += ["", "## Known method differences (reported, not adjusted)", ""]
        lines += [f"- **{i['id']}**: {i['note']}" for i in notes]
    return "\n".join(lines) + "\n"
